"use client";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { Cpu, CheckCircle2, AlertCircle } from "lucide-react";

const MIN_TOKEN_LEN = 4; // kode lebih pendek dari ini dianggap bukan hasil scan
const MAX_KEY_GAP_MS = 100; // alat scan mengetik jauh lebih cepat daripada manusia

const extractToken = (text) => {
  let tok = String(text || "").trim();
  const m = tok.match(/[?&]guest=([\w-]+)/);
  if (m) return m[1];
  try {
    const t = new URL(tok).searchParams.get("guest");
    if (t) return t;
  } catch {}
  return tok;
};

// Alat scan hardware bekerja seperti keyboard: mengetik isi QR dengan cepat lalu menekan Enter.
// Karena input dihapus, komponen ini memasang listener keydown global. Setelah check-in berhasil,
// onCheckedIn memicu popup "Sudah Check-in" di komponen induk.
export default function DeviceScanClient({
  operator = "",
  deviceId = "",
  tableName = "",
  paused = false,
  onCheckedIn,
}) {
  const [results, setResults] = useState([]);
  const [busy, setBusy] = useState(false);

  const bufferRef = useRef("");
  const lastKeyRef = useRef(0);
  const busyRef = useRef(false);
  const lastScanRef = useRef({ token: "", at: 0 });
  const ctx = useRef({});
  ctx.current = { operator, deviceId, tableName, paused, onCheckedIn };

  const pushResult = (r) =>
    setResults((list) =>
      [{ ...r, at: Date.now() + Math.random() }, ...list].slice(0, 25),
    );

  const processScan = async (raw) => {
    const token = extractToken(raw);
    if (!token || busyRef.current) return;

    // cegah scan ganda dari token yang sama (2 detik)
    const now = Date.now();
    if (
      lastScanRef.current.token === token &&
      now - lastScanRef.current.at < 2000
    )
      return;
    lastScanRef.current = { token, at: now };

    const { operator, deviceId, tableName, onCheckedIn } = ctx.current;
    if (!operator.trim()) {
      toast.error("Isi operator dulu");
      return;
    }

    busyRef.current = true;
    setBusy(true);
    try {
      const info = await fetch(
        `/api/guests/lookup/checkin?token=${encodeURIComponent(token)}`,
      )
        .then((r) => r.json())
        .catch(() => null);
      const g = info?.guest;
      if (!g) {
        const msg = info?.error || "Tamu tidak ditemukan";
        pushResult({ ok: false, message: msg, token });
        toast.error(msg);
        return;
      }
      if (g.invitation?.selfieVerification) {
        const msg = "Undangan ini butuh selfie — gunakan tab Scan Kamera";
        pushResult({ ok: false, message: msg, token });
        toast.error(msg);
        return;
      }
      if (g.guestType === "INDIVIDUAL" && g.checkedInAt) {
        const msg = `${g.name} sudah check-in`;
        pushResult({ ok: false, message: msg, token });
        toast.error(msg);
        return;
      }

      const count = Math.max(1, Math.min(g.quota || 1, 50));
      const res = await fetch("/api/guests/lookup/checkin", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          token: g.token,
          deviceId: deviceId || null,
          operatorName: operator.trim(),
          tableName: tableName || null,
          count,
        }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data?.error) {
        const msg = data?.error || "Check-in gagal";
        pushResult({ ok: false, message: msg, token });
        toast.error(msg);
        return;
      }
      pushResult({
        ok: true,
        name: data.guest?.name || token,
        count: data.count || count,
        token,
      });
      toast.success(`✓ ${data.guest?.name || "Sudah check-in"}`);
      if (data.guest)
        onCheckedIn?.(data.guest, data.count || count, data.checkInId); // → popup Sudah Check-in
    } finally {
      busyRef.current = false;
      setBusy(false);
    }
  };

  useEffect(() => {
    const onKeyDown = (e) => {
      if (ctx.current.paused) {
        bufferRef.current = "";
        return;
      }
      const t = e.target;
      const tag = t?.tagName;
      if (
        tag === "INPUT" ||
        tag === "TEXTAREA" ||
        tag === "SELECT" ||
        t?.isContentEditable
      )
        return;
      if (e.ctrlKey || e.metaKey || e.altKey) return;

      const now = Date.now();
      if (now - lastKeyRef.current > MAX_KEY_GAP_MS) bufferRef.current = "";
      lastKeyRef.current = now;

      if (e.key === "Enter") {
        const code = bufferRef.current;
        bufferRef.current = "";
        if (code.length >= MIN_TOKEN_LEN) {
          e.preventDefault();
          processScan(code);
        }
        return;
      }
      if (e.key.length === 1) bufferRef.current += e.key;
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="grid gap-6 lg:grid-cols-2">
      <div className="rounded-2xl bg-white border border-primary/10 p-6 space-y-4">
        <div className="flex items-center gap-2">
          <Cpu className="h-5 w-5 text-primary" />
          <h3 className="font-serif text-xl font-semibold">Scanner Device</h3>
        </div>
        <div
          className={`rounded-xl border-2 border-dashed p-8 text-center ${paused ? "border-amber-300 bg-amber-50" : "border-emerald-300 bg-emerald-50"}`}
        >
          <p className="font-medium">
            {busy
              ? "Memproses…"
              : paused
                ? "Scan ditunda (tutup popup terlebih dulu)"
                : "Siap memindai — arahkan alat scan ke QR tamu"}
          </p>
          <p className="text-xs text-muted-foreground mt-1">
            Tidak perlu klik apa pun. Setelah QR terbaca, popup check-in akan
            muncul otomatis.
          </p>
        </div>
      </div>

      <div className="rounded-2xl bg-white border border-primary/10 p-6">
        <h3 className="font-serif text-lg font-semibold mb-3">Scan Terakhir</h3>
        {results.length === 0 ? (
          <p className="text-sm text-muted-foreground">Belum ada scan.</p>
        ) : (
          <ul className="space-y-2 max-h-[420px] overflow-auto">
            {results.map((r) => (
              <li
                key={r.at}
                className={`flex items-center gap-2 text-sm rounded-md px-3 py-2 ${r.ok ? "bg-emerald-50 text-emerald-800" : "bg-red-50 text-red-700"}`}
              >
                {r.ok ? (
                  <CheckCircle2 className="h-4 w-4" />
                ) : (
                  <AlertCircle className="h-4 w-4" />
                )}
                <span className="font-medium">{r.ok ? r.name : r.message}</span>
                {r.ok && r.count > 1 ? (
                  <span className="text-xs">(+{r.count})</span>
                ) : null}
                <span className="ml-auto text-xs opacity-60 font-mono">
                  {r.token.slice(0, 10)}
                </span>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
